insert into public.reference_passages
  (id, source_id, branch, personnel_category, occupation_code, occupation_title, section_type, rank_band, components, heading, chapter, body, body_sha256, pdf_page_start, pdf_page_end, printed_page, sort_order, effective_from, effective_to, cumulative, skill_level)
values
  ('0f509fbb-9206-5900-a32c-a330003e27e4', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'development', 'O-1..O-2', null, 'Lieutenant development — overview', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'FA58 does not have any lieutenants.', '76049a01caf7aae56e00e5f413d890f5e65f6b7aae12fdf1ac929cb78e6bb806', 5, 5, null, 0, null, null, false, null),
  ('e38e69c3-4437-516c-a582-dec080d1e262', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'development', 'O-3', null, 'Captain development — overview', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'Approximately 10% of FA58 are captains who serve in developmental positions at the United States Military Academy or the Army Enterprise Marketing Office. The FA58 career path does not support captains serving in operational roles outside of these assignments except for trainees and students. Officers may be selected for FA58 as captains between their 5th and 11th year of service. Prior to transitioning to FA58, officers will be experienced and successful in their basic branch, having completed the Captains’ Career Course.', '1ff184b8beece5c6d9e385b55d4996603ce42eaa7cfd2bfaaaf580ac296966b5', 5, 6, null, 1, null, null, false, null),
  ('5f8d37b9-81e8-56a2-b6ee-b6c2d68e631c', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'training', 'O-3', null, 'Captain development — Education', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'Most selected FA58 officers will have completed ACS with an MBA, Business/Marketing Analytics degree, or other related graduate degree in the fields of marketing, behavioral economics, or decision sciences. If officers do not possess a graduate degree in marketing, the FA58 Proponent office will decide on ACS candidacy. This determination is contingent on the desires of the officer, the officer’s prior experience with marketing, graduate testing aptitude, and the needs of FA58.', 'f0c8dbce306a733d682406a9ce2b7f2bbabbc7c2beebd568cae9e2c8a413cfd2', 6, 6, null, 2, null, null, false, null),
  ('384e3459-2528-5e01-86cd-9f811ae0aa6c', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'assignments', 'O-3', null, 'Captain development — Assignments', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'Marketing officers are often selected while completing an ACS utilization tour. Officers will complete their full tour before conducting a permanent change of station in support of FA58. Some officers selected for FA58, while still serving their utilization tour, may have the opportunity to work on marketing projects or research before reporting to their first assignment as a Marketing Officer. These opportunities are dependent on the officer’s existing professional obligations. For example, FA58s stationed at West Point as faculty members due to ACS utilizations may have the opportunity to begin conducting marketing research and working on projects with the Marketing Research Cell, the FA58 Proponent, and OEMA.', '92be3c8858c46bc7f95f5c74900e985592f4257cf098ed1be7f9899781462769', 6, 6, null, 3, null, null, false, null),
  ('75668694-b66c-54f2-97da-691857e16ebe', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'development', 'O-3', null, 'Captain development — Developmental and subsequent assignments', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'Since FA58 officers are usually selected as senior captains, the combination of basic branch assignments with initial marketing officer assignments provides a sufficiently broad experience to build a successful career in Army Marketing.', '23f32c8b7bc9ff9c6ee4b0dd4fc16c06994222f93c1fc981d0093eee6667bd01', 6, 6, null, 4, null, null, false, null),
  ('2f1ed4e0-b523-5b39-9d75-3475aca27b99', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'self_development', 'O-3', null, 'Captain development — Self-development', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'FA58 officers should take opportunities to broaden their knowledge of marketing through courses, professional readings, and research into marketing related topics.', 'c53cc5cde031fba6fd7f3905801109a2e2734d89e893d4ed419197b6470e90b1', 6, 6, null, 5, null, null, false, null),
  ('8c5c1f72-2c5a-58f1-8517-1db92c483f9e', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'training', 'O-4', null, 'Major development — Education', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'Completion of a MEL4/JPME I level producing course (usually Distance Learning Common Core or Satellite ILE and an Individual Qualification Course (IQC) in lieu of AOC, or completion of Resident, Satellite, or Distance Learning ILE with AOC portion) prior to being eligible for selection to lieutenant colonel.
(a) FA58 officers may satisfy the ILE IQC education requirement by completing an in-residence graduate degree related to the fields of marketing such as an MBA, DBA, or MS in Marketing or Data Analytics, behavioral economics, or similar, and complete the FA58 integration course also known as the AMFC. Officers seeking to satisfy their ILE IQC education requirement must submit their graduate transcript to the FA Proponent for approval. Approval is contingent upon the officer’s completion of a degree directly related to marketing, behavioral economics, or data analytics, and the degree being earned in residence.
(b) FA58 majors will, every two years, pursue educational opportunities, coordinated by the FA58 Proponent office, to become experts in the various roles of Army Marketing, usually consisting of executive-level education courses or marketing practitioner education courses, professional certifications, and industry training courses.
(c) Majors may be selected by the FA58 Proponent office to pursue a doctoral degree in a field such as marketing, business administration, analytics, or behavioral economics at a leading civilian education institution through the ACS program.', '99f8757b4ca8f27b13654f0554cd7d613a10d284e0bcb777a6f49358d6164c25', 6, 7, null, 6, null, null, false, null),
  ('2fbca211-d68e-5681-a1cd-812ddb938b73', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'assignments', 'O-4', null, 'Major development — Assignments', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'FA58 officers will likely serve their first assignment at AEMO headquarters where they will apply their knowledge and skills within the Marketing Execution (MX) or Strategy, Innovation and Data Directorate (SIDD). In limited cases, officers may serve their first assignment at an AEMO regional office, part of the Regional Marketing Directorate (RMD), or within an accession headquarters (TRADOC, USAREC, or USACC). All FA58 assignments are considered Key Developmental (KD) assignments.', '53b43e680cd724968d7dbced639a9573c96f9d0e053f45a776c25d6cf73b7490', 7, 7, null, 7, null, null, false, null),
  ('27c6b00e-8eb6-5929-ac82-3547919464b2', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'development', 'O-4', null, 'Major development — Developmental and subsequent assignments', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'Following an FA58 officer’s initial assignment, marketing officers may be assigned to AEMO regional offices or an accession headquarters where they will help direct, integrate, and synchronize the Army’s marketing activities, strategies, and brand alignment. FA58 has a Training with Industry (TWI) program, which may place select FA58 officers with industry-leading marketing corporations to learn from marketing practitioners.', '683826dd508bb454d9c59cb3146d94d32e10a1f10b64c598476cd6f0dd52f071', 7, 7, null, 8, null, null, false, null),
  ('774af3db-a2d6-58e6-8802-560c430883b1', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'development', 'O-4', null, 'Major development — Additional guidance', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'The following are considered appropriate initial assignments for FA58 majors.
(a) JAMRS LNO (National Capital Region)
(b) Branch Managers (MX and SIDD)
(c) RMO Marketing Analyst (RMD)
(d) USMA Admissions
(e) AMP Manager', '89d7d7a82f1fd70beefd7f0aec0918ba94e5ceea27a5e815cba2009938fc5b07', 7, 7, null, 9, null, null, false, null),
  ('67e99aaa-ef5d-51f8-bc45-71f643a0580d', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'development', 'O-4', null, 'Major development — Additional guidance', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'The following are considered appropriate second assignments for FA58 majors.
(a) Product Managers (SIDD)
(b) RMO Program Managers (RMD)
(c) Accessions HQ Marketing Analyst
(d) Marketing Research Cell (OEMA)
(e) Accessions Battalion Executive/Operations Officer', '37b9b06af13c262d19568fedc1f6544374460f2a65e565692f30b55b8340beee', 7, 7, null, 10, null, null, false, null),
  ('1e6ed8a8-9cc0-55df-b6ef-c42147e89d83', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'self_development', 'O-4', null, 'Major development — Self-development', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'FA58 majors will actively pursue organizational and self-development opportunities to maintain professional competency within the marketing field. Additionally, FA58 majors should consider publication in academic and practitioner journals to showcase excellence, organizational achievement, and advancement of scholarly insight across the marketing field.', '239977b39dd192d4064bc40f345ddedec50b6408e5c5adf6f64a7c3e1239b8fd', 7, 7, null, 11, null, null, false, null),
  ('8a2852d5-d977-58aa-9e98-b67e254ae7d1', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'training', 'O-5', null, 'Lieutenant colonel development — Education', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'Lieutenant colonels that have displayed high performance and potential and have completed a master’s degree in a field approved by the FA58 Proponent, before being selected for lieutenant colonel, or if joining through direct commission have substantial prior professional experience in marketing, behavioral economics, or the decision sciences. A select number of officers will pursue an advanced degree in a doctoral program approved by the FA58 Proponent, sponsored through ACS. Additionally, a select number of lieutenant colonels will have the opportunity to attend SSC or a Fellowship equivalent.', '5a144428508294ec5119e353ec8858a2eeaace8e2c2148c578ade45fced03928', 7, 8, null, 12, null, null, false, null),
  ('e9aeae02-1af7-5323-bf9e-6161df2949af', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'assignments', 'O-5', null, 'Lieutenant colonel development — Key developmental assignments', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'All FA58 lieutenant colonel billets are considered KD positions.', '1891216908e63c1a0bdf9209c2d54106b295b82f9c0269f5e65b44a37340a9cd', 8, 8, null, 13, null, null, false, null),
  ('9b98c5ce-c6c4-5b30-be15-ebc8712febf1', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'development', 'O-5', null, 'Lieutenant colonel development — Developmental and broadening assignments', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'FA58 lieutenant colonels should seek assignments within the Functional Area that directly contribute to, and develop, the Army marketing profession to include accession battalion commands or Professor of Military Science assignments within USACC. Additionally, the FA58 Proponent may select lieutenant colonels for the Training with Industry program. FA58 lieutenant colonels are expected to serve in positions of increased responsibility and leadership in support of the marketing enterprise which may include OCLL, HRC, HQDA G-1, and OCPA.', '979b8c7d798abd5e5d037fcd2d891db53b6b8e5e30053f3426c99241f1baf909', 8, 8, null, 14, null, null, false, null),
  ('edaa1ab4-cdad-5922-bff9-fc5399c49eac', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'development', 'O-5', null, 'Lieutenant colonel development — Additional guidance', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'The following are considered appropriate initial assignments for FA58 lieutenant colonels.
(a) Branch Chief (MX and SIDD)
(b) RMO Operations Chief (RMD)
(c) Stakeholder Marketing Chief
(d) FA58 Proponent', 'eda4b1711dec7a5e8a9191c3778e1a25fcc1636a6eefe671794361b5a57db442', 8, 8, null, 15, null, null, false, null),
  ('d3142c50-31aa-5d93-b238-96bdc0168828', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'development', 'O-5', null, 'Lieutenant colonel development — Additional guidance', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'The following are considered appropriate second assignments for FA58 lieutenant colonels.
(a) Product Chief (SIDD)
(b) RMO Chief (RMD)
(c) Accessions Battalion Command', '8e5dd971bdfc7738e935fa6b4d20eedb9fd1705b09ac5bb82fab4b9b725e18dc', 8, 8, null, 16, null, null, false, null),
  ('1fafade5-a3bc-5b02-af7a-86988806a196', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'self_development', 'O-5', null, 'Lieutenant colonel development — Self-development', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'Marketing lieutenant colonels should attend industry conferences and training courses related to their areas of focus and pursue professional development programs such as continuing executive education sponsored by the FA58 Proponent office.', 'f5c37dcf4db8e0ff488a3475a51e13b2fb9523d71b08b1c57c6130c81ab86824', 8, 8, null, 17, null, null, false, null),
  ('3baf996d-8a1c-551c-bd3c-a683c05e3e51', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'training', 'O-6', null, 'Colonel development — Education', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'FA58 colonels will have completed a master’s degree in a field approved by the FA58 Proponent before being selected for colonel or have substantial prior professional experience in marketing. A select number of colonels will have the opportunity to attend a resident SSC or Fellowship equivalent.', 'a716683408bbdcac9336ae60fbbe8963e765fe883884d1f439689a07c4f92c65', 8, 8, null, 18, null, null, false, null),
  ('c24794e3-faed-5a26-b2e5-3f2bf0ce0ef1', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'assignments', 'O-6', null, 'Colonel development — Key developmental assignments', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'All FA58 colonel billets are considered KD positions.', '9b0a33c4c79cd8663ed7bb61000521d13857acecf2460185005d7d677749feef', 8, 8, null, 19, null, null, false, null),
  ('c26c6185-0b81-5c8e-b79a-4130675b436b', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'development', 'O-6', null, 'Colonel development — Developmental and broadening assignments', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'Officers selected for colonel will seek assignments within the Functional Area that directly contribute to and develop the Army Marketing profession. These positions could include command-level positions within the Accessions Enterprise or at marketing-related offices such as the Office of the Secretary of Defense Personnel & Readiness or as an advisor to a senior leader of another military component. Colonels contribute to the Functional Area by serving in critical assignments within the Accessions Enterprise.', '1b360249dffb9cc35b0b697998a63171374217839936e4a1ed3570d9432f8258', 8, 9, null, 20, null, null, false, null),
  ('577b90ef-76d7-5171-b87f-c11a409cc8c9', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'development', 'O-6', null, 'Colonel development — The following are considered appropriate assignments for FA58 colonels', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', '(a) Director of Strategy and Innovation
(b) Director of Marketing Execution
(c) Director of Regional Marketing
(d) Senior Marketing Advisor (ASA M&RA)
(e) Chief of Staff, AEMO
(f) Accessions Brigade Command', 'ca144749b7a9fc6dccc0d68612a1c59467072726b27d8448bfa90fbf71776909', 9, 9, null, 21, null, null, false, null),
  ('ae214fa3-1014-5fd0-a2e5-fdea45339c20', '71ded726-5873-5c01-87df-3097629345e7', 'Army', 'officer', '58A', 'MARKETING OFFICER', 'self_development', 'O-6', null, 'Colonel development — Self-development', 'Army Enterprise Marketing and Behavioral Economics Officer (FA58) career pamphlet, DA PAM 600-3 chapter (25 October 2023)', 'Marketing colonels should attend industry conferences and training courses related to their areas of focus and pursue professional development programs such as continuing executive education sponsored by the FA58 Proponent office.', 'bd5387e1e5c68b73ba8b3880c667c6ca0dc246003140eef208631fde3d281b89', 9, 9, null, 22, null, null, false, null);
